// src/pages/shared/ProfilePage/ProfilePage.jsx

import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Button from '../../../components/ui/Button/Button';
import styles from './ProfilePage.module.css';

// Recebe 'user' como prop
const ProfilePage = ({ user, onNavigate }) => {
  return (
    <ContentWrapper title="Meu Perfil">
      <div className={styles.profileInfo}>
        <div className={styles.infoItem}>
          <span className={styles.label}>Nome</span>
          {/* Exibe os dados do utilizador logado */}
          <span className={styles.value}>{user.name}</span>
        </div>
        <div className={styles.infoItem}>
          <span className={styles.label}>Email</span>
          <span className={styles.value}>{user.email}</span>
        </div>
        <div className={styles.infoItem}>
          <span className={styles.label}>Cargo</span>
          <span className={styles.value}>{user.role}</span>
        </div>
      </div>
      <div className={styles.actions}>
        <Button onClick={() => onNavigate('edit_profile')}>
          Editar Perfil
        </Button>
      </div>
    </ContentWrapper>
  );
};

export default ProfilePage;
